\\\"label\\\":\\\"Published\\\"},\\\"created_at\\\":\\\"2026-01-05T14:10:26.000000Z\\\",\\\"updated_at\\\":\\\"2026-01-06T04:25:07.000000Z\\\",\\\"slugable\\\":{\\\"id\\\":444,\\\"key\\\":\\\"businesses-organizations\\\",\\\"reference_type\\\":\\\"Botble\\\\\\\\Page\\\\\\\\Models\\\\\\\\Page\\\",\\\"reference_id\\\":110,\\\"prefix\\\":\\\"\\\"}}}},{\\\"menuItem\\\":{\\\"id\\\":53,\\\"menu_id\\\":1,\\\"parent_id\\\":51,\\\"reference_id\\\":111,\\\"reference_type\\\":\\\"Botble\\\\\\\\Page\\\\\\\\Models\\\\\\\\Page\\\",\\\"url\\\":\\\"\\/success-stories\\\",\\\"icon_font\\\":\\\"\\\",\\\"position\\\":1,\\\"title\\\":\\\"Success Stories\\\",\\\"css_class\\\":\\\"\\\",\\\"target\\\":\\\"_self\\\",\\\"has_child\\\":0,\\\"icon_image\\\":\\\"\\\",\\\"metadata\\\":[],\\\"reference\\\":{\\\"id\\\":111,\\\"name\\\":\\\"Success Stories\\\",\\\"content\\\":\\\"[hero-banner title=\\\\\\\"Success Stories\\\\\\\" subtitle=\\\\\\\"PATIENT TESTIMONIALS\\\\\\\" description=\\\\\\\"Real stories from real patients who have experienced exceptional care at Metro Health Hospital.\\\\\\\" background_image=\\\\\\\"sliders\\/slider1-1.png\\\\\\\" background_color=\\\\\\\"rgb(20, 23, 108)\\\\\\\" enable_lazy_loading=\\\\\\\"no\\\\\\\"][\\/hero-banner]\\\\n\\\\n[testimonials style=\\\\\\\"style-2\\\\\\\" title=\\\\\\\"What Our Customers Say\\\\\\\" subtitle=\\\\\\\"PATIENT EXPERIENCES\\\\\\\" description=\\\\\\\"Hear from patients who have trusted Metro Health Hospital with their healthcare needs.\\\\\\\" testimonial_ids=\\\\\\\"1,2,3,4\\\\\\\" background_color=\\\\\\\"rgb(255, 255, 255)\\\\\\\" enable_lazy_loading=\\\\\\\"yes\\\\\\\"][\\/testimonials]\\\\n\\\\n[content-feature-list style=\\\\\\\"style-2\\\\\\\" title=\\\\\\\"Why Patients Choose Metro Health\\\\\\\" subtitle=\\\\\\\"EXCELLENCE IN CARE\\\\\\\" description=\\\\\\\"Our commitment to quality healthcare has earned the trust of thousands of patients.\\\\\\\" quantity=\\\\\\\"6\\\\\\\" title_1=\\\\\\\"Expert Medical Team\\\\\\\" description_1=\\\\\\\"Highly skilled professionals with decades of combined experience across all specialties.\\\\\\\" icon_1=\\\\\\\"ti ti-users\\\\\\\" title_2=\\\\\\\"State-of-the-Art Facilities\\\\\\\" description_2=\\\\\\\"Modern equipment and comfortable amenities for optimal care and recovery.\\\\\\\" icon_2=\\\\\\\"ti ti-building-hospital\\\\\\\" title_3=\\\\\\\"Patient-Centered Approach\\\\\\\" description_3=\\\\\\\"Every decision we make is focused on your health and well-being with personalized treatment.\\\\\\\" icon_3=\\\\\\\"ti ti-heart-handshake\\\\\\\" title_4=\\\\\\\"24\\/7 Emergency Care\\\\\\\" description_4=\\\\\\\"Round-the-clock emergency services with rapid response teams and advanced life support.\\\\\\\" icon_4=\\\\\\\"ti ti-ambulance\\\\\\\" title_5=\\\\\\\"Comprehensive Services\\\\\\\" description_5=\\\\\\\"From routine check-ups to complex surgical procedures across all medical specialties.\\\\\\\" icon_5=\\\\\\\"ti ti-stethoscope\\\\\\\" title_6=\\\\\\\"Proven Track Record\\\\\\\" description_6=\\\\\\\"Over 50,000 patients served with a 98% satisfaction rate since 2011.\\\\\\\" icon_6=\\\\\\\"ti ti-award\\\\\\\" background_color=\\\\\\\"rgb(248, 249, 250)\\\\\\\" enable_lazy_loading=\\\\\\\"yes\\\\\\\"][\\/content-feature-list]\\\\n\\\\n[counter style=\\\\\\\"style-2\\\\\\\" title=\\\\\\\"Our Impact in Numbers\\\\\\\" subtitle=\\\\\\\"SUCCESS METRICS\\\\\\\" description=\\\\\\\"These numbers tell the story of our commitment to excellence.\\\\\\\" quantity=\\\\\\\"4\\\\\\\" title_1=\\\\\\\"Years of Service\\\\\\\" number_1=\\\\\\\"13\\\\\\\" unit_1=\\\\\\\"+\\\\\\\" title_2=\\\\\\\"Patients Served\\\\\\\" number_2=\\\\\\\"50000\\\\\\\" unit_2=\\\\\\\"+\\\\\\\" title_3=\\\\\\\"Success Rate\\\\\\\" number_3=\\\\\\\"98\\\\\\\" unit_3=\\\\\\\"%\\\\\\\" title_4=\\\\\\\"Medical Specialists\\\\\\\" number_4=\\\\\\\"50\\\\\\\" unit_4=\\\\\\\"+\\\\\\\" background_color=\\\\\\\"rgb(20, 23, 108)\\\\\\\" enable_lazy_loading=\\\\\\\"yes\\\\\\\"][\\/count