INSERT INTO `pages` (`id`, `name`, `content`, `user_id`, `image`, `template`, `description`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Homepage', '<shortcode>[hero-banner style=\"slider\" title=\"Your Health, Our Priority\" subtitle=\"METRO HEALTH HOSPITAL\" description=\"Delivering world-class healthcare services with compassion, expertise, and state-of-the-art facilities since 2011.\" button_label=\"Learn More\" button_url=\"/about\" background_color=\"rgb(20, 23, 108)\" enable_lazy_loading=\"no\"][/hero-banner]</shortcode><shortcode>[about-us-information style=\"style-2\" title=\"Welcome to Metro Health Hospital\" description=\"Established in 2011, Metro Health Hospital is a premier healthcare facility located at Abrepo Junction in Kumasi Metropolis. We combine cutting-edge medical technology with compassionate care.\" image=\"services/welcome.png\" image_1=\"services/about-small2.png\" quantity=\"3\" title_1=\"Patient-Centered Care\" description_1=\"Every decision we make is focused on your health and well-being with personalized treatment plans.\" icon_1=\"ti ti-heart-handshake\" title_2=\"Expert Medical Team\" description_2=\"Highly skilled professionals with decades of combined experience across all medical specialties.\" icon_2=\"ti ti-stethoscope\" title_3=\"Modern Facilities\" description_3=\"State-of-the-art equipment and comfortable amenities for optimal care and recovery.\" icon_3=\"ti ti-building-hospital\" background_color=\"rgb(255, 255, 255)\" enable_lazy_loading=\"yes\"][/about-us-information]</shortcode><shortcode>[services style=\"modern\" title=\"Comprehensive Medical Services\" subtitle=\"SPECIALIZED CARE\" description=\"From routine check-ups to complex surgical procedures, our multidisciplinary team provides expert care across all medical specialties.\" service_ids=\"1,2,3,4,5,6\" limit=\"6\" button_label=\"View All Services\" button_url=\"/services\" background_color=\"rgb(248, 249, 250)\" enable_lazy_loading=\"yes\"][/services]</shortcode><shortcode>[blog-posts style=\"style-1\" category_ids=\"21\" title=\"News &amp; Articles\" limit=\"6\" background_image=\"sliders/bg-news.png\" background_color=\"transparent\" enable_lazy_loading=\"yes\"][/blog-posts]</shortcode><shortcode>[contact-block style=\"style-1\" title=\"Ready to Experience Quality Healthcare?\" subtitle=\"SCHEDULE YOUR APPOINTMENT\" description=\"Our dedicated team is ready to provide you with exceptional care.\" phone_number=\"+233 24 185 0091\" button_label=\"Contact Us Now\" button_url=\"/contact-us\" background_image=\"sliders/slider1.png\" background_color=\"rgb(87, 50, 181)\" enable_lazy_loading=\"yes\"][/contact-block]</shortcode>', 1, NULL, 'homepage', '', 'published', '2026-01-04 15:32:00', '2026-01-07 19:46:06'),
(2, 'Contact Us', '<p>&nbsp;</p><shortcode>[contact-form display_fields=\"phone,email,subject,address\" mandatory_fields=\"phone\" title=\"Send Us a Message\" description=\" Fill out the form below and our team will respond within 24 hours. We\'re committed to providing you with prompt and professional service. \" quantity=\"6\" title_1=\"Visit Our Hospital \" icon_1=\"ti ti-map-pin-filled\" description_1=\"4 Barekese Road, Abrepo Junction Near Angel Fm, Kumasi, Ghana \" title_2=\"Call Us Anytime\" icon_2=\"ti ti-file-phone\" description_2=\"+233 24 185 0091 &lt;br/&gt;+233 24 855 5596 &lt;br/&gt;+233 26 484 0859 &lt;br/&gt;+233 50 163 7303 \" title_3=\"Email\" icon_3=\"ti ti-mail-check\" description_3=\"info@metrohealthgh.com&lt;br/&gt;\r\nappointments@metrohealthgh.com\" enable_lazy_loading=\"no\"][/contact-form]</shortcode><shortcode>[google-map height=\"500\"]Metro Health Hospital, Abrepo Junction, Kumasi, Ghana[/google-map]</shortcode><shortcode>[contact-block style=\"style-2\" title=\"Medical Emergency?\" subtitle=\"24/7 EMERGENCY HOTLINE\" phone_number=\"+233 24 185 0091\" button_label=\"Book Appointment\" button_url=\"/booking\" background_image=\"sliders/slider1.png\" background_color=\"rgb(20, 23, 108)\" enable_lazy_loading=\"yes\"][/contact-block]</shortcode>', 1, NULL, 'full-width', '', 'published', '2026-01-04 15:32:00', '2026-01-08 08:01:46'),
(3, 'Blog', '', 1, NULL, NULL, NULL, 'published', '2026-01-04 15:32:00', '2026-01-04 15:32:00'),
(4, 'Business About', '[about-us-information style=&quot;style-11&quot; title=&quot;We Help Organizations To Make Ultimate Businesses Growth Success&quot; subtitle=&quot;SIMPLY KNOW ABOUT&quot; description=&quot;We successfully cope with tasks of varying complexityprovide longerty term guarantees and regularly master new Practice Area technol ogiesOur portfolio includes dozen&quot; image=&quot;general/about-us-information-11.jpg&quot; image_1=&quot;general/about-us-information-11-1.jpg&quot; image_2=&quot;general/about-us-information-11-2.png&quot; quantity=&quot;3&quot; title_1=&quot;Medicare Advantage Plans&quot; title_2=&quot;Analysis &amp; Research&quot; title_3=&quot;100% Secure Money Back&quot; data_count=&quot;15+&quot; data_count_description=&quot;World Best Agency &lt;br&gt; Award Got&quot; button_label=&quot;Contact With Us&quot; button_url=&quot;/contact-us&quot; background_color=&quot;transparent&quot; enable_lazy_loading=&quot;no&quot;][/about-us-information][brands name_1=&quot;Door Dash&quot; image_1=&quot;brands/1.png&quot; url_1=&quot;/&quot; name_2=&quot;Discord&quot; image_2=&quot;brands/1.png&quot; url_2=&quot;/&quot; name_3=&quot;Airbnb&quot; image_3=&quot;brands/1.png&quot; url_3=&quot;/&quot; name_4=&quot;Norton&quot; image_4=&quot;brands/1.png&quot; url_4=&quot;/&quot; name_5=&quot;Naturewave&quot; image_5=&quot;brands/1.png&quot; url_5=&quot;/&quot; quantity=&quot;5&quot; background_color=&quot;transparent&quot;][/brands][about-us-information style=&quot;style-12&quot; title=&quot;Digital Solutions For Your Online Business&quot; subtitle=&quot;WHY WE ARE THE BEST&quot; description=&quot;We successfully cope with tasks of varying complexity provide area longerty guarantees and regularly master new Practice Following gies heur.&quot; quantity=&quot;4&quot; title_1=&quot;Business Solutions&quot; description_1=&quot;Semper egetuis kelly for tellus urna area condition.&quot; icon_1=&quot;ti ti-chart-histogram&quot; title_2=&quot;Finance Planning&