INSERT INTO `teams` (`id`, `name`, `photo`, `title`, `location`, `socials`, `status`, `created_at`, `updated_at`, `content`, `phone`, `email`, `address`, `website`, `description`) VALUES
(1, 'Mr. Stephen Tawiah', 'news/team2.png', 'Managing Director', 'Kumasi, Ghana', '{\"facebook\":null,\"twitter\":null,\"instagram\":null}', 'published', '2026-01-05 02:58:14', '2026-01-05 03:04:22', '<p>Mr. Stephen Tawiah serves as the Managing Director of Metro Health Hospital, providing strategic leadership and overseeing all operations. His vision and dedication ensure the hospital maintains its commitment to excellence in healthcare delivery.</p>', '0241850091', 'md@metrohealthgh.com', '4 Barekese Road, Kumasi', NULL, 'Leading Metro Health Hospital with strategic vision and excellence.'),
(2, 'Dr. (Mrs) Phyllis Tawiah', 'news/team2-1.png', 'Medical Director', 'Kumasi, Ghana', '{\"facebook\":null,\"twitter\":null,\"instagram\":null}', 'published', '2026-01-05 02:58:14', '2026-01-05 03:06:19', '<p>Dr. (Mrs) Phyllis Tawiah is the Medical Director of Metro Health Hospital, bringing extensive experience in healthcare management and clinical excellence. She leads our medical team with a commitment to providing world-class patient care.</p>', '0241850091', 'medical.director@metrohealthgh.com', '4 Barekese Road, Kumasi', NULL, 'Ensuring clinical excellence across all medical departments.'),
(3, 'Veronica Sabeng Poku', 'news/team5.png', 'Administrator', 'Kumasi, Ghana', '{\"facebook\":null,\"twitter\":null,\"instagram\":null}', 'published', '2026-01-05 02:58:14', '2026-01-05 03:06:39', '<p>Veronica Sabeng Poku serves as the Administrator of Metro Health Hospital, managing day-to-day operations and ensuring smooth functioning of all hospital departments. Her organizational skills and dedication contribute to excellent patient care.</p>', '0248555596', 'admin@metrohealthgh.com', '4 Barekese Road, Kumasi', NULL, 'Managing hospital operations with efficiency and dedication.'),
(4, 'Dr. Odeefour Ofori Amanfo', 'news/team3.png', 'Deputy Administrator', 'Kumasi, Ghana', '{\"facebook\":null,\"twitter\":null,\"instagram\":null}', 'published', '2026-01-05 02:58:14', '2026-01-05 03:06:52', '<p>Dr. Odeefour Ofori Amanfo serves as the Deputy Administrator of Metro Health Hospital, supporting administrative operations and ensuring quality healthcare delivery. His medical expertise and administrative skills make him an invaluable member of the leadership team.</p>', '0264840859', 'deputy.admin@metrohealthgh.com', '4 Barekese Road, Kumasi', NULL, 'Supporting hospital administration with medical expertise and leadership.'),
(5, 'Mary Ann Koomson', 'news/team4.png', 'Human Resource Manager', 'Kumasi, Ghana', '{\"facebook\":null,\"twitter\":null,\"instagram\":null}', 'published', '2026-01-05 02:59:58', '2026-01-05 03:07:06', '<p>Mary Ann Koomson serves as the Human Resource Manager of Metro Health Hospital, managing recruitment, training, and staff development. She ensures Metro Health attracts and retains top medical talent and maintains a positive work environment.</p>', '0241850091', 'hr@metrohealthgh.com', '4 Barekese Road, Kumasi', NULL, 'Building and developing our exceptional healthcare team.');
INSERT INTO `testimonials` (`id`, `name`, `content`, `image`, `company`, `status`, `created_at`, `updated_at`) VALUES
(1, 'David K. Amoah', 'From the moment I arrived, I knew Metro Health Hospital was the right place—swift, caring staff made my pneumonia recovery smooth, and it\'ll always be my first choice.', NULL, 'Santasi, Kumasi', 'published', '2026-01-05 07:26:57', '2026-01-05 07:26:57'),
(2, 'Mahammed Faruk', 'Metro Health is our trusted healthcare choice, professional staff and a state-of-the-art facility make it the hospital my family always relies on.', NULL, 'Kronum, Kumasi', 'published', '2026-01-05 07:26:57', '2026-01-05 07:26:57'),
(3, 'Janet Owusu Gyafuah', 'Metro Health Hospital delivers world-class, 24/7 medical care with specialists always on hand—setting the standard for quality healthcare.', NULL, 'Tepa, Ashanti', 'published', '2026-01-05 07:26:57', '2026-01-05 07:26:57'),
(4, 'Mohammed Abdulai Tanka', 'Metro Health keeps a clean, well-maintained environment and offers impressive medical packages, making healthcare completely stress-free.', NULL, 'Director, Lamsta Hostel, Accra', 'published', '2026-01-05 07:26:57', '2026-01-05 07:26:57');
